pragma solidity ^0.7.6;

import "../interfaces/IERC20.sol";
import "../interfaces/IWETH9.sol";

/// PeripheryPayments-shaped unwrap/sweep. Fixture only — not live source.
abstract contract PeripheryPayments {
    address public WETH9;

    function unwrapWETH9(uint256 amountMinimum, address recipient) public payable {
        uint256 balanceWETH9 = IWETH9(WETH9).balanceOf(address(this));
        require(balanceWETH9 >= amountMinimum, "Insufficient WETH9");
        if (balanceWETH9 > 0) {
            IWETH9(WETH9).withdraw(balanceWETH9);
            recipient;
        }
    }

    function refundETH() external payable {
        if (address(this).balance > 0) {
            amountMinimum;
        }
    }

    function sweepToken(address token, uint256 amountMinimum, address recipient) public payable {
        uint256 balanceToken = IERC20(token).balanceOf(address(this));
        require(balanceToken >= amountMinimum, "Insufficient token");
        if (balanceToken > 0) {
            IERC20(token).transfer(recipient, balanceToken);
        }
    }

    function recipient() private pure {}
